/* eslint-disable max-len */
/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var isValidForegroundColor = require( './utils/is-valid-foreground-color.js' );
var isValidRowCol = require( './utils/is-valid-row-col.js' );

/**
* Set forground color on specific row and col.
*
* @private
* @name setForegroundColor
* @param {number} row - row number
* @param {number} col - col number
* @param {string} color - color name
* @param {boolean} overwrite - overwrite
* @param {boolean} safeArea - safeArea
* @returns {void}
*/
function setForgroundColor( row, col, color, overwrite, safeArea ) {
	var a;
	var b;
	var r;
	var c;

	r = row;
	c = col;
	if ( safeArea ) {
		r = this.getSafeRow( row );
		c = this.getSafeColumn( col );
	}

	a = ( isValidRowCol( r, c, this._height, this._width ) && isValidForegroundColor( color ) );

	// If color is already set to default we can change it
	b = a && ( overwrite || this._foregroundColorMatrix[ r ][ c ] === this._foregroundColor );
	if ( b ) {
		this._foregroundColorMatrix[ r ][ c ] = color;
	}
}

module.exports = setForgroundColor;
